//! Events generated by a state change are queued on the document, so they are
//! dispatched even when the change does not come from an event driver (e.g. a
//! programmatic focus change).

use super::{document, node};
use blitz_dom::{Document, EventDriver, EventHandler, NodeId};
use blitz_traits::events::{DomEvent, DomEventData, EventDispatchSource, EventState};
use dioxus::prelude::*;
use std::{cell::RefCell, rc::Rc};

#[derive(Clone, Default)]
struct RecordingHandler(Rc<RefCell<Vec<(NodeId, String)>>>);

impl EventHandler for RecordingHandler {
    fn handle_event(
        &mut self,
        _chain: &[NodeId],
        event: &mut DomEvent,
        _doc: &mut dyn Document,
        _event_state: &mut EventState,
    ) {
        self.0
            .borrow_mut()
            .push((event.target, event.name().to_string()));
    }
}

const HTML: &str =
    r#"<html><body><input id="a" type="text"><input id="b" type="text"></body></html>"#;

#[test]
fn programmatic_focus_changes_dispatch_focus_events() {
    let mut doc = document(HTML);
    let a = node(&doc, "#a");
    let b = node(&doc, "#b");

    doc.set_focus_to(a);
    doc.set_focus_to(b);
    doc.clear_focus();
    assert!(doc.has_pending_events());

    let handler = RecordingHandler::default();
    EventDriver::new(&mut doc, handler.clone()).flush_pending_events();
    assert!(!doc.has_pending_events());

    let expected = [
        (a, "focus"),
        (a, "focusin"),
        (a, "blur"),
        (a, "focusout"),
        (b, "focus"),
        (b, "focusin"),
        (b, "blur"),
        (b, "focusout"),
    ]
    .map(|(id, name)| (id, name.to_string()));
    assert_eq!(*handler.0.borrow(), expected);
}

#[test]
fn dioxus_poll_dispatches_queued_focus_events() {
    fn app() -> Element {
        let mut focused = use_signal(|| false);
        rsx! {
            input { id: "input", onfocus: move |_| focused.set(true) }
            div { id: "seen", "{focused}" }
        }
    }

    let mut doc = super::component(app);
    let input = node(&doc.inner(), "#input");
    doc.inner_mut().set_focus_to(input);
    assert!(doc.inner().has_pending_events());
    assert!(doc.poll(None));

    let base = doc.inner();
    let seen = base.get_node(node(&base, "#seen")).unwrap().text_content();
    assert_eq!(seen, "true");
}

#[test]
fn queued_events_for_dropped_nodes_are_discarded() {
    let mut doc = document(HTML);
    let a = node(&doc, "#a");

    doc.set_focus_to(a);
    doc.mutate().remove_and_drop_node(a);

    let handler = RecordingHandler::default();
    EventDriver::new(&mut doc, handler.clone()).flush_pending_events();
    assert!(handler.0.borrow().is_empty());
}

/// Focuses the other node whenever one of the two is focused
struct FocusPingPong {
    nodes: [NodeId; 2],
    focus_events: Rc<RefCell<usize>>,
}

impl EventHandler for FocusPingPong {
    fn handle_event(
        &mut self,
        _chain: &[NodeId],
        event: &mut DomEvent,
        doc: &mut dyn Document,
        _event_state: &mut EventState,
    ) {
        if event.name() == "focus" {
            *self.focus_events.borrow_mut() += 1;
            let other = self.nodes[(event.target == self.nodes[0]) as usize];
            doc.inner_mut().set_focus_to(other);
        }
    }
}

#[test]
fn flush_stops_when_handlers_keep_queueing_events() {
    let mut doc = document(HTML);
    let nodes = [node(&doc, "#a"), node(&doc, "#b")];

    doc.set_focus_to(nodes[0]);

    let focus_events = Rc::new(RefCell::new(0));
    let handler = FocusPingPong {
        nodes,
        focus_events: focus_events.clone(),
    };
    EventDriver::new(&mut doc, handler).flush_pending_events();

    // The flush returned, and the events it did not get to are still queued
    assert!(*focus_events.borrow() > 1);
    assert!(doc.has_pending_events());
}

#[test]
fn only_input_pointer_events_dispatch_a_mouse_event() {
    let mut doc = document(HTML);
    let a = node(&doc, "#a");

    let data = doc
        .get_node(a)
        .unwrap()
        .synthetic_click_event_data(Default::default());

    let names_for = |doc: &mut blitz_dom::BaseDocument, source| {
        let event = DomEvent::new(a, DomEventData::PointerMove(data.clone()), source);
        assert_eq!(event.is_trusted(), source != EventDispatchSource::Script);
        doc.queue_event(event);
        let handler = RecordingHandler::default();
        EventDriver::new(doc, handler.clone()).flush_pending_events();
        let names: Vec<String> = handler.0.borrow().iter().map(|e| e.1.clone()).collect();
        names
    };

    // The default action can add hover events after these
    let input = names_for(&mut doc, EventDispatchSource::Input);
    assert_eq!(input[..2], ["pointermove", "mousemove"]);

    for source in [EventDispatchSource::UserAgent, EventDispatchSource::Script] {
        let names = names_for(&mut doc, source);
        assert_eq!(names[0], "pointermove");
        assert!(!names.iter().any(|name| name == "mousemove"));
    }
}

#[test]
fn scroll_events_for_the_same_target_are_coalesced() {
    let mut doc = document(
        r#"<html><body>
            <div id="scroller" style="width: 100px; height: 100px; overflow: scroll">
                <div style="height: 1000px"></div>
            </div>
            <input id="a" type="text">
        </body></html>"#,
    );
    let scroller = node(&doc, "#scroller");
    let a = node(&doc, "#a");

    doc.scroll_node_by(scroller, 0.0, -10.0);
    doc.scroll_node_by(scroller, 0.0, -10.0);
    // An event in between keeps the scroll events either side of it apart
    doc.set_focus_to(a);
    doc.scroll_node_by(scroller, 0.0, -10.0);

    let scroll_tops = Rc::new(RefCell::new(Vec::new()));
    let handler = ScrollTopRecorder(scroll_tops.clone());
    EventDriver::new(&mut doc, handler).flush_pending_events();

    assert_eq!(*scroll_tops.borrow(), [20.0, 30.0]);
}

struct ScrollTopRecorder(Rc<RefCell<Vec<f64>>>);

impl EventHandler for ScrollTopRecorder {
    fn handle_event(
        &mut self,
        _chain: &[NodeId],
        event: &mut DomEvent,
        _doc: &mut dyn Document,
        _event_state: &mut EventState,
    ) {
        if let DomEventData::Scroll(data) = &event.data {
            self.0.borrow_mut().push(data.scroll_top);
        }
    }
}
